//! Actual same-host full Original subject and selected PlayerLink question.
use super::*;
use std::io;
#[path="../../../../analyze/fixtures/native-player-link-workspace/fixture.rs"]mod source;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_config;
fn player_host(case:&str)->(crate::runner_host::BuildHost,BuildRequest,PathBuf){let(mut host,mut request,root)=fixture("/datum/placeholder\n");for(relative,bytes)in source::files(case){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}for index in 0..130{std::fs::write(root.join(format!("code/extra_{index:04}.dm")),format!("// real player-link source {index}\n")).unwrap();}let intent=request.policy_inputs.as_mut().unwrap();intent.analysis_context=Some(AnalysisContext::OriginalAnalyze0290);intent.workspace_auxiliary=vec![crate::policy_request::WorkspaceAuxiliaryQuestion::PlayerLink];run(&mut host,&request);(host,request,root)}
#[test]fn actual_original_player_link_full_subject_over_130_files_preserves_whole_semantic_domain(){for case in source::CASES{let(host,_,_)=player_host(case);current(&host,|snapshot|snapshot.with_original_player_link_policy(|data,_,_|{assert_eq!(data.metadata().name,"player_link");if *case=="exempt"{assert!(data.sites().is_empty());}else{assert!(!data.sites().is_empty());}if *case=="noncode"{assert!(data.sites().iter().any(|site|site.rel=="maps/player.dm"));}assert!(data.notes().is_empty()&&data.allow_used().is_empty());assert!(data.sites().iter().all(|site|site.msg==dq_analyze::player_link_policy::MESSAGE));println!("NATIVE_PLAYER_LINK_FULL={}",serde_json::json!({"case":case,"sites":data.sites(),"notes":data.notes(),"allow_used":data.allow_used()}));Ok(())}).unwrap());}}
#[test]fn actual_original_player_link_refuses_foreign_subject_owner_quota_and_keeps_first_output_io(){let(mut host,request,_)=player_host("basic");let queries=Arc::clone(host.query_db());let first=current(&host,|snapshot|snapshot.with_original_player_link_policy(|data,_,_|Ok(serde_json::json!(data.sites()))).unwrap());let before=queries.db().stats(dm_query::Kind(4)).computed;current(&host,|snapshot|{let guard=snapshot.workspace_native_read().unwrap();let workspace=snapshot.native_workspace.as_ref().unwrap();let child=snapshot.workspace_semantic_inputs(crate::policy_request::WorkspaceAuxiliaryQuestion::PlayerLink).unwrap();let subject=snapshot.analysis_subject.as_ref().unwrap();let foreign=crate::query_db::QueryDb::default();let mut called=false;assert!(foreign.with_original_workspace_player_link_guard(workspace,&guard,child,subject,|_,_,_|{called=true;Ok(())}).is_err());assert!(!called);assert_eq!(queries.with_original_workspace_player_link_guard_limit(workspace,&guard,child,subject,Some(1),|_,_,_|{called=true;Ok(())}).unwrap_err().kind(),std::io::ErrorKind::OutOfMemory);assert!(!called);let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(60));assert_eq!(snapshot.with_original_player_link_policy(|_,_,_|{token.cancel();Err::<(),_>(std::io::Error::from_raw_os_error(1450))}).unwrap_err().raw_os_error(),Some(1450));drop(binding);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||snapshot.with_original_player_link_policy(|_,_,_|->io::Result<()>{panic!("actual player-link output unwind")}))).is_err());snapshot.with_original_player_link_policy(|data,_,_|{assert_eq!(serde_json::json!(data.sites()),first);Ok(())}).unwrap();});run(&mut host,&request);current(&host,|snapshot|snapshot.with_original_player_link_policy(|data,_,_|{assert_eq!(serde_json::json!(data.sites()),first);Ok(())}).unwrap());assert_eq!(queries.db().stats(dm_query::Kind(4)).computed,before);let(mut denied,mut wrong,_)=fixture("/mob/proc/check()\n    key = 1\n");wrong.policy_inputs.as_mut().unwrap().workspace_auxiliary=vec![crate::policy_request::WorkspaceAuxiliaryQuestion::Tracked];run(&mut denied,&wrong);current(&denied,|snapshot|{let mut called=false;assert!(snapshot.with_original_player_link_policy(|_,_,_|{called=true;Ok(())}).is_err());assert!(!called)});}

#[test]fn actual_original_player_link_public_pages_keep_hard_messages_without_fabricated_source(){use crate::daemon::query::{self,QueryRequest,SourceQuery};let(mut host,mut request,root)=player_host("noncode");let config_path=root.join("tools/ci/lint_scopes.toml");let overlay=std::fs::read_to_string(&config_path).unwrap();std::fs::write(&config_path,report_config::with_overlay(&overlay)).unwrap();run(&mut host,&request);let state=host.query_state();let state=state.lock().unwrap();let snapshot=state.snapshot.as_ref().unwrap();let mut query=QueryRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),timeout_seconds:Some(60),project:request.project.clone(),defines:Default::default(),engine_template:None,bootstrap_catalog:false,expected_revision:Some(format!("{:032x}",snapshot.tree.identity())),expected_source_revision:Some(format!("{:032x}",snapshot.source_revision)),expected_policy_revision:Some(format!("{:032x}",snapshot.policy_revision.unwrap())),queries:Vec::new(),source_queries:vec![SourceQuery::NativeWorkspaceSemanticReportPage{root:root.clone(),configuration:root.join("tools/ci/lint_scopes.toml"),lints:vec!["player_link".into()],cursor:None,limit:1}]};let mut total=0;let mut aggregate:Option<String>=None;loop{let reply=query::evaluate_snapshot(&query,&snapshot.tree,&state).unwrap();query::validate_effect_batch_for_test(&query,&reply).unwrap();let row:serde_json::Value=serde_json::from_str(reply.jsonl.trim()).unwrap();assert_eq!(row["row"],"source_native_workspace_semantic_report");assert_eq!(row["lint_whitelist"],serde_json::json!(["player_link"]));assert_eq!(row["full_policy_parity"],false);if let Some(old)=&aggregate{assert_eq!(row["aggregate_id"].as_str(),Some(old.as_str()))}else{aggregate=Some(row["aggregate_id"].as_str().unwrap().to_owned())}for item in row["items"].as_array().unwrap(){assert_eq!(item["kind"],"hard_site");assert!(item.get("source_text").is_none());assert_eq!(item["site"]["msg"],dq_analyze::player_link_policy::MESSAGE);}total+=row["count"].as_u64().unwrap();if row["next_cursor"].is_null(){assert_eq!(total,row["total_items"].as_u64().unwrap());break}if let SourceQuery::NativeWorkspaceSemanticReportPage{cursor:next,..}=&mut query.source_queries[0]{*next=Some(serde_json::from_value(row["next_cursor"].clone()).unwrap())}}assert!(total>0);struct Fail;impl std::io::Write for Fail{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}assert_eq!(snapshot.write_native_workspace_semantic_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&["player_link".into()],None,128,&snapshot.tree,&mut Fail).unwrap_err().raw_os_error(),Some(1450));let mut wrong=query;wrong.source_queries=vec![SourceQuery::NativeWorkspaceSemanticReportPage{root:root.clone(),configuration:root.join("tools/ci/lint_scopes.toml"),lints:vec!["player_link".into(),"sem/reads".into()],cursor:None,limit:1}];assert!(query::evaluate_snapshot(&wrong,&snapshot.tree,&state).is_err());}
